392→// run executes a subcommand on the external binary and returns stdout bytes.
393→// If stdin is non-nil it is piped to the process. On non-zero exit, stderr is
394→// included in the returned error.
395→func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
396→	cmd := exec.CommandContext(ctx, e.binaryPath, args...)
397→
398→	// Set environment: repo root + protocol version
399→	cmd.Env = append(cmd.Environ(),
400→		"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
401→	)
402→	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
403→		cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
404→		cmd.Dir = repoRoot
405→	}
406→
407→	if stdin != nil {
408→		cmd.Stdin = bytes.NewReader(stdin)
409→	}
410→
411→	var stdoutBuf, stderrBuf bytes.Buffer
412→	cmd.Stdout = &stdoutBuf
413→	cmd.Stderr = &stderrBuf
414→
415→	if err := cmd.Run(); err != nil {
416→		errMsg := stderrBuf.String()
417→		if errMsg != "" {
418→			return nil, fmt.Errorf("%s: %s", args[0], errMsg)
419→		}
420→		return nil, fmt.Errorf("%s: %w", args[0], err)
421→	}
422→
423→	return stdoutBuf.Bytes(), nil
424→}
